(6123580, 901466, 62249, '<td valign="top">You get points from me for creatively stretching the definition of the challenge (yes, I had to look up laplacian). However, I know from past painful experience with DPC that most voters won''t look it up, won''t think outside the box, and will vote harshly because they don''t get it. They''ll probably make plenty of "doesn''t meet challenge" comments. Good luck to you with this shot. 6</td>', 'You get points from me for creatively stretching the definition of the challenge (yes, I had to look up laplacian). However, I know from past painful experience with DPC that most voters won''t look it up, won''t think outside the box, and will vote harshly because they don''t get it. They''ll probably make plenty of "doesn''t meet challenge" comments. Good luck to you with this shot. 6', '2010-08-08 20:31:15.000000', NULL, 1),
(6123584, 901593, 62249, '<td valign="top">Image is a little soft but otherwise ok. Good composition. Her forehead could maybe be darkened a tiny bit.</td>', 'Image is a little soft but otherwise ok. Good composition. Her forehead could maybe be darkened a tiny bit.', '2010-08-08 20:33:24.000000', NULL, 1),
(6123588, 901521, 62249, '<td valign="top">Definitely looks like he works in a call center.</td>', 'Definitely looks like he works in a call center.', '2010-08-08 20:34:40.000000', NULL, 1),
(6123590, 901396, 62249, '<td valign="top">This is a different take on the challenge. I like the setup.</td>', 'This is a different take on the challenge. I like the setup.', '2010-08-08 20:35:45.000000', NULL, 1),
(6123591, 901563, 62249, '<td valign="top">The boots are a hoot. So''s the rotary dial phone.</td>', 'The boots are a hoot. So''s the rotary dial phone.', '2010-08-08 20:36:18.000000', NULL, 1),
(6123596, 900378, 62249, '<td valign="top">Love the facial expression. Lighting is a bit flat.</td>', 'Love the facial expression. Lighting is a bit flat.', '2010-08-08 20:37:14.000000', NULL, 1),
(6123605, 901600, 62249, '<td valign="top">Lighting is kind of harsh. It''s casting unpleasant shadows from the book. But composition is good. Might want to lose the white wrist band if you were really shooting this for stock. That makes the shot look like "patient" rather than "operator."</td>', 'Lighting is kind of harsh. It''s casting unpleasant shadows from the book. But composition is good. Might want to lose the white wrist band if you were really shooting this for stock. That makes the shot look like "patient" rather than "operator."', '2010-08-08 20:39:23.000000', NULL, 1),
(6123608, 901508, 62249, '<td valign="top">I appreciate graphic manipulations of photos, although lots of DPCers don''t. Good luck with this shot.</td>', 'I appreciate graphic manipulations of photos, although lots of DPCers don''t. Good luck with this shot.', '2010-08-08 20:40:16.000000', NULL, 1),
(6123613, 901443, 62249, '<td valign="top">Looks like you had fun setting this up. Could be a little better lit to avoid the hotspot on his forehead and the relative darkness on the left side of the photo.</td>', 'Looks like you had fun setting this up. Could be a little better lit to avoid the hotspot on his forehead and the relative darkness on the left side of the photo.', '2010-08-08 20:41:22.000000', NULL, 1),
(6123619, 901437, 62249, '<td valign="top">Lovely. Sepia treatment works well for this. Right side is slightly too dark, but still a nice shot.</td>', 'Lovely. Sepia treatment works well for this. Right side is slightly too dark, but still a nice shot.', '2010-08-08 20:42:34.000000', NULL, 1),
(6123622, 901513, 62249, '<td valign="top">Funny. Great sales-y expression on the model''s face.</td>', 'Funny. Great sales-y expression on the model''s face.', '2010-08-08 20:43:07.000000', NULL, 1),
(6123624, 901442, 62249, '<td valign="top">Cute idea and cute composition (cute cat too). Needs sharper focus.</td>', 'Cute idea and cute composition (cute cat too). Needs sharper focus.', '2010-08-08 20:43:58.000000', NULL, 1),
(6123626, 900293, 62249, '<td valign="top">Cute dog. Would like to see a bit more of his front paw. Good lighting on the dog''s fur.</td>', 'Cute dog. Would like to see a bit more of his front paw. Good lighting on the dog''s fur.', '2010-08-08 20:45:07.000000', NULL, 1),
(6123631, 901597, 62249, '<td valign="top">Pretty sure I''ve spoken with a few of these operators. Well composed. Focus seems a tad soft on the woody''s body, but I still like the shot.</td>', 'Pretty sure I''ve spoken with a few of these operators. Well composed. Focus seems a tad soft on the woody''s body, but I still like the shot.', '2010-08-08 20:46:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6123634, 901147, 62249, '<td valign="top">Fun idea. Posed hand on the head is a bit over the top (har!), and your Tech sign is lost in the shadows. Still, looks like you enjoyed setting this up.</td>', 'Fun idea. Posed hand on the head is a bit over the top (har!), and your Tech sign is lost in the shadows. Still, looks like you enjoyed setting this up.', '2010-08-08 20:47:48.000000', NULL, 1),
