(6123650, 901459, 62249, '<td valign="top">Snicker. This is amusing and well shot. Good job.</td>', 'Snicker. This is amusing and well shot. Good job.', '2010-08-08 20:51:43.000000', NULL, 1),
(6123651, 901323, 62249, '<td valign="top">Ha! I love this. Clever idea, well composed, well lit, and well shot. Good job. Only slightly negative comment is that his pen gets a bit lost in the stripe pattern of the shirt.</td>', 'Ha! I love this. Clever idea, well composed, well lit, and well shot. Good job. Only slightly negative comment is that his pen gets a bit lost in the stripe pattern of the shirt.', '2010-08-08 20:51:48.000000', NULL, 1),
(6123917, 901409, 38162, '<td valign="top">windy title hurts very creative try here.</td>', 'windy title hurts very creative try here.', '2010-08-08 23:55:31.000000', NULL, 1),
(6123918, 901437, 38162, '<td valign="top">title takes more time to read than looking at your art.</td>', 'title takes more time to read than looking at your art.', '2010-08-08 23:56:35.000000', NULL, 1),
(6124256, 901466, 104841, '<td valign="top">well it will be interesting to see who has done first/second year maths and gets the title, though the shot does not quite look like the Laplacian symbol. The bottom of frame could have been a little bit sharper though.</td>', 'well it will be interesting to see who has done first/second year maths and gets the title, though the shot does not quite look like the Laplacian symbol. The bottom of frame could have been a little bit sharper though.', '2010-08-09 05:31:17.000000', NULL, 1),
(6124258, 901593, 104841, '<td valign="top">For me I find the teal top a little bit out of place colour wise, I would consider converting this shot to mono and see how it looks.</td>', 'For me I find the teal top a little bit out of place colour wise, I would consider converting this shot to mono and see how it looks.', '2010-08-09 05:33:16.000000', NULL, 1),
(6124341, 901409, 114969, '<td valign="top">Very funny shot :-) <br/>My own entry is doing pretty well right now, and I figure this one is my main competition ;-) I will also vote fairly, doing otherwise would be pretty pathetic.<br/> <br/>Technically, this is a very good shot, although the plain white background is very "dense" and distracting in my eye... However, most stock photos comply with this "rule", so I have to say that your entry is way more a stock photo than mine. Congrats :-)<br/> <br/>Oh btw, what is this poor green thing that got crushed?</td>', 'Very funny shot :-) My own entry is doing pretty well right now, and I figure this one is my main competition ;-) I will also vote fairly, doing otherwise would be pretty pathetic. Technically, this is a very good shot, although the plain white background is very "dense" and distracting in my eye... However, most stock photos comply with this "rule", so I have to say that your entry is way more a stock photo than mine. Congrats :-) Oh btw, what is this poor green thing that got crushed?', '2010-08-09 09:03:25.000000', NULL, 1),
(6124521, 901302, 117559, '<td valign="top">I can see this more being used as an angry customer.  You have been creative though and attempted something different from the normal operator images. 9</td>', 'I can see this more being used as an angry customer.  You have been creative though and attempted something different from the normal operator images. 9', '2010-08-09 11:50:10.000000', NULL, 1),
(6124526, 901437, 117559, '<td valign="top">I like this image, you have been creative and the colouring makes it look old and antique like.<br/>I''m not sure however if a company would want to use it as a stock image so I took one point off. 8</td>', 'I like this image, you have been creative and the colouring makes it look old and antique like.I''m not sure however if a company would want to use it as a stock image so I took one point off. 8', '2010-08-09 11:51:42.000000', NULL, 1),
(6124548, 901481, 117559, '<td valign="top">Clean, simple image.  I can see it being used by a company, however personally it doesn''t tick the creative/innovative part of the challenge so I take off one point. 8</td>', 'Clean, simple image.  I can see it being used by a company, however personally it doesn''t tick the creative/innovative part of the challenge so I take off one point. 8', '2010-08-09 11:59:50.000000', NULL, 1),
